/**
 * Converts exposure time in nanoseconds to a camera shutter speed string.
 * @param exposureTimeNs Exposure time in nanoseconds
 * @return Formatted shutter speed string (e.g., "1/30s", "1/1000s", "0.5s")
 */
fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "0s"

    val seconds = exposureTimeNs / 1_000_000_000.0

    // For very fast shutter speeds, use fractional representation
    if (seconds < 1.0) {
        val denominator = (1.0 / seconds).roundToInt()
        // Check if it's a common shutter speed
        when (denominator) {
            2 -> return "1/2s"
            4 -> return "1/4s"
            8 -> return "1/8s"
            15 -> return "1/15s"
            30 -> return "1/30s"
            60 -> return "1/60s"
            125 -> return "1/125s"
            250 -> return "1/250s"
            500 -> return "1/500s"
            1000 -> return "1/1000s"
            2000 -> return "1/2000s"
            4000 -> return "1/4000s"
            8000 -> return "1/8000s"
            else -> {
                // For other values, show as decimal if it's not a whole number fraction
                val decimalValue = (1.0 / denominator).roundToDouble(2)
                if (decimalValue >= 0.1) {
                    return "$decimalValue s"
                } else {
                    return "1/$denominator s"
                }
            }
        }
    } else {
        // For slow shutter speeds, show as decimal seconds
        val decimalSeconds = seconds.roundToDouble(2)
        if (decimalSeconds == decimalSeconds.toInt()) {
            return "${decimalSeconds.toInt()}s"
        } else {
            return "$decimalSeconds s"
        }
    }
}

