    Returns every move for the side to move in UCI notation.
    Handles normal piece movement, captures, and pawn double pushes.
    Ignores castling, en passant, promotion, and check/pin legality.
    """
    # Parse FEN
    parts = fen.split()
    board_str = parts[0]
    side_to_move = parts[1]  # 'w' or 'b'

    # Convert board string to 2D array
    board = []
    ranks = board_str.split('/')
    for rank in ranks:
        row = []
        for char in rank:
            if char.isdigit():
                # Empty squares
                row.extend(['.'] * int(char))
            else:
                # Piece
                row.append(char)
        board.append(row)

    moves = []

    # Generate moves for each piece
    for row in range(8):
        for col in range(8):
            piece = board[row][col]
            if piece == '.':
                continue

            # Check if piece belongs to side to move
            is_white = piece.isupper()
            if (side_to_move == 'w' and not is_white) or (side_to_move == 'b' and is_white):
                continue

            # Generate moves based on piece type
            piece_type = piece.lower()
            if piece_type == 'p':
                moves.extend(generate_pawn_moves(board, row, col, is_white))
            elif piece_type == 'n':
                moves.extend(generate_knight_moves(board, row, col, is_white))
            elif piece_type == 'b':
                moves.extend(generate_bishop_moves(board, row, col, is_white))
            elif piece_type == 'r':
                moves.extend(generate_rook_moves(board, row, col, is_white))
            elif piece_type == 'q':
                moves.extend(generate_queen_moves(board, row, col, is_white))
            elif piece_type == 'k':
                moves.extend(generate_king_moves(board, row, col, is_white))

    return moves

